// The stickers every stall starts with: the kind that are already there when
// you arrive. A name tag nobody filled in, the sticker off a piece of fruit,
// and a price that was never true. Drawn once by a script and kept as PNGs;
// their ids are fixed so a pile can name them.

export const DEFAULT_STICKERS: Record<string, string> = {
  trash00001:
    "data:image/png;base64,",
  trash00002:
    "data:image/png;base64,",
  trash00003:
    "data:image/png;base64,",
};

// a small pile to begin with, a little different in each stall: [id, copies]
export function starterPile(stall: number): { id: string; left: number }[] {
  const ids = Object.keys(DEFAULT_STICKERS);
  const pick = (n: number) => ids[(stall + n) % ids.length];
  return [
    { id: pick(0), left: 10 },
    { id: pick(1), left: 10 },
    { id: pick(2), left: 7 },
    { id: pick(0), left: 4 },
  ];
}
